mapper.select:
SELECT t.user_id AS userId, COUNT(1) AS examTimes, SUM(CASE WHEN t.failCount = 0 THEN 1 ELSE 0 END) AS passedTimes FROM ( SELECT s.user_id, s.exam_id, SUM(CASE WHEN s.pass_flag = 1 THEN 0 ELSE 1 END) AS failCount FROM answer_sheet s INNER JOIN exam e ON e.id = s.exam_id AND e.deleted = 0 AND e.exam_mode = 'FORMAL'
s.status = 'PUBLISHED' AND s.final_score IS NOT NULL AND e.dept_id = #{deptId}
GROUP BY s.user_id, s.exam_id ) t GROUP BY t.user_id
